export function formatarPreco(centavos: number, moeda = 'BRL'): string {
  let s = String(Math.floor(centavos / 100));
  let r = '';
  for (let i = s.length - 1, c = 0; i >= 0; i--, c++) { if (c && c % 3 === 0) r = '.' + r; r = s[i] + r; }
  return (moeda === 'BRL' ? 'R$ ' : '$ ') + r + ',' + String(centavos % 100).padStart(2, '0');
}

